class BoardType(Enum):
    """A-Share board types with their characteristics"""
    MAIN_BOARD = "main_board"
    CHINEXT = "chinext"
    STAR_MARKET = "star_market"
    ST_STOCK = "st_stock"
    UNKNOWN = "unknown"


class OrderSide(Enum):
    """Order side enumeration"""
    BUY = "buy"
    SELL = "sell"


class OrderType(Enum):
    """Order type enumeration"""
    LIMIT = "limit"
    MARKET = "market"


@dataclass
class Order:
    """Represents a buy/sell order"""
    side: OrderSide
    stock_code: str
    order_type: OrderType
    price: float
    volume: int  # In lots (multiples of 100)
    filled_volume: int = 0
    filled_price: float = 0.0
    filled_date: Optional[str] = None
    status: str = "pending"
    order_id: str = ""
    create_time: Optional[str] = None
    total_value: float = 0.0

    @property
    def total_value(self) -> float:
        """Calculate total order value (price * volume * 100)"""
        return self.price * self.volume * 100


@dataclass
class Position:
    """Represents a stock position in the portfolio"""
    stock_code: str
    open_price: float
    volume: int  # Number of shares
    avg_price: float  # Weighted average cost
    cost: float = 0.0
    settled: bool = False

    @property
    def unrealized_pnl(self) -> float:
        """Calculate unrealized P&L"""
        if self.volume == 0:
            return 0.0
        current_value = self.open_price * self.volume
        return current_value - self.cost


