        if date in holidays:
            return MarketCalendar._next_trading_date(dt, holidays)
        return date

    @staticmethod
    def _next_trading_date(dt: datetime, holidays: Dict[str, List[str]]) -> str:
        current = dt
        while current.weekday() in [5, 6]:
            current += timedelta(days=1)
        current_date = current.strftime('%Y-%m-%d')
        if current_date in holidays:
            return MarketCalendar._next_trading_date(current, holidays)
        return current_date

    @staticmethod
    def get_settlement_date(trading_date: str) -> str:
        try:
            dt = datetime.strptime(trading_date, '%Y-%m-%d')
        except ValueError:
            return trading_date
        dt = MarketCalendar._next_trading_date(dt, {})
        return dt.strftime('%Y-%m-%d')

    @staticmethod
    def is_trading_day(date: str) -> bool:
        weekdays = ['Sun', 'Sat']
        try:
            dt = datetime.strptime(date, '%Y-%m-%d')
            if dt.strftime('%A') in weekdays:
                return False
            holidays_file = os.path.join(
                os.path.dirname(__file__), 'data/holidays/cn_trading_holidays_2024.csv'
            )
            if os.path.exists(holidays_file):
                holidays = ConfigLoader.load_holidays_csv(holidays_file)
                if date in holidays:
                    return False
            return True
        except ValueError:
            return False


class FeeCalculator:
    """Calculate A-share transaction fees"""

    def __init__(self, fee_config: Dict):
        self.commission_rate = fee_config.get('commission_rate', 0.00025)
        self.min_commission = fee_config.get('commission', {}).get('min_amount', 5.0)
        self.stamp_tax_rate = fee_config.get('stamp_tax_rate', 0.001)
        self.transfer_fee_rate = fee_config.get('transfer_fee_rate', 0.00002)

    def calculate(self, side: OrderSide, stock_code: str, price: float, volume: int) -> Tuple[float, float, float]:
        total_value = price * volume * 100
        commission = total_value * self.commission_rate
        if commission < self.min_commission and volume > 0:
            min_commission_per_share = self.min_commission / 100
            if price < min_commission_per_share:
                commission = self.min_commission
            else:
                commission = max(commission, self.min_commission)

        stamp_tax = total_value * self.stamp_tax_rate if side == OrderSide.SELL else 0.0
        transfer_fee = total_value * self.transfer_fee_rate

        return commission, stamp_tax, transfer_fee


class PriceValidator:
    """Validate order prices against board limits"""

    def __init__(self, price_limits: Dict):
        self.price_limits = price_limits

    def get_price_limit(self, stock_code: str, current_price: float) -> float:
        board = BoardClassifier.get_board_type(stock_code)
        return self.price_limits.get(board, 0.10)

    def is_price_valid(self, price: float, stock_code: str, current_price: float) -> bool:
        limit = self.get_price_limit(stock_code, current_price)
        valid_upper = current_price * (1 + limit)
        return current_price - limit <= price <= valid_upper


class MarketDataLoader:
    """Load and process market data"""

    def __init__(self, data_dir: str):
        self.data_dir = data_dir
        self.data: Dict[str, pd.DataFrame] = {}
        self.stock_codes = set()

    def load_all(self) -> Dict[str, pd.DataFrame]:
        import glob
        csv_files = glob.glob(os.path.join(self.data_dir, '*.csv'))
        for filepath in csv_files:
            filename = os.path.basename(filepath)
            df = pd.read_csv(filepath)
            self.data[filename] = df
            code = os.path.splitext(filename)[0]
            self.stock_codes.add(code)
        return self.data

    def get_dataframe(self, stock_code: str) -> Optional[pd.DataFrame]:
        filename = f"{stock_code}_daily.csv"
        if filename in self.data:
            return self.data[filename].copy()
        return None

    def sort_dataframe(self, df: pd.DataFrame) -> pd.DataFrame:
        df = df.copy()
        if 'date' in df.columns:
            df = df.set_index('date')
            df.sort_index(ascending=False, inplace=True)
        return df


class PaperTradingEngine:
    """
    Paper Trading Engine for A-Share market
    """

    def __init__(self, initial_capital: float, trading_rules: Dict, fee_config: Dict):
        self.initial_capital = initial_capital
        self.trading_rules = trading_rules
        self.fee_config = fee_config

        # Initialize price limits from trading rules
        self.price_limits = {
            'main_board': trading_rules.get('price_limits', {}).get('main_board', 0.10),
            'chinext': trading_rules.get('price_limits', {}).get('chinext', 0.20),
            'star_market': trading_rules.get('price_limits', {}).get('star_market', 0.20),
            'st_stocks': trading_rules.get('price_limits', {}).get('st_stocks', 0.05)
        }

        # Initialize fee calculator
        self.fee_calculator = FeeCalculator(fee_config)

        # Initialize price validator
        self.price_validator = PriceValidator(self.price_limits)

        # Trading calendar
        self.holidays = ConfigLoader.load_holidays_csv(os.path.join(
            os.path.dirname(__file__), 'data/holidays/cn_trading_holidays_2024.csv'
        ))

        # Portfolio state
        self.cash = initial_capital
        self.position: Dict[str, Position] = {}
        self.pending_orders: List[Order] = []
        self.trades: List[Trade] = []
        self.settlements: Dict[str, Tuple[str, float]] = {}

    def reset(self, initial_capital: Optional[float] = None):
        if initial_capital is None:
            initial_capital = self.initial_capital
        self.cash = initial_capital
        self.position = {}
        self.pending_orders = []
        self.trades = []
        self.settlements = {}
        self.fee_calculator = FeeCalculator(self.fee_config)

    def _execute_order(
        self, side: OrderSide, stock_code: str, price: float, volume: int, timestamp: datetime
    ) -> Tuple[bool, Optional[Order], Optional[Trade]]:
        if stock_code not in self.price_limits:
            self.price_limits[stock_code] = 0.10

        if not self.price_validator.is_price_valid(price, stock_code, price):
            return False, None, None

        lot_size = BoardClassifier.get_board_type(stock_code, None).lot_size
        volume_lots = volume // lot_size

        if volume_lots == 0:
            return False, None, None

        current_date = MarketCalendar.get_trading_date(timestamp.strftime('%Y-%m-%d'))
        if not current_date:
            return False, None, None

        if current_date not in self.data:
            return False, None, None

        market_data = self.data[current_date]
        current_price = market_data[market_data['date'] == current_date]['close'].values[0]

        if side == OrderSide.BUY:
            limit = self.price_validator.get_price_limit(stock_code, current_price)
            valid_upper = current_price * (1 + limit)
            if price > valid_upper or price < current_price:
                return False, None, None

            order_value = price * volume * 100
            total_fee = order_value * self.fee_calculator.commission_rate
            total_fee = max(total_fee, self.fee_calculator.min_commission)

            if self.cash < order_value + total_fee:
                return False, None, None

            order = Order(
                side=side, stock_code=stock_code, order_type=OrderType.LIMIT,
                price=price, volume=volume_lots, filled_volume=0,
                filled_price=0.0, filled_date=None, status="pending",
                total_value=order_value
            )
            return True, order, None

        else:  # SELL
            if stock_code not in self.position:
                return False, None, None

            pos = self.position[stock_code]
            if pos.volume < volume_lots:
                return False, None, None

            order = Order(
                side=side, stock_code=stock_code, order_type=OrderType.LIMIT,
                price=price, volume=volume_lots, filled_volume=0,
                filled_price=0.0, filled_date=None, status="pending",
                total_value=price * volume * 100
            )
            return True, order, None

        return False, None, None

    def place_order(
        self, side: OrderSide, stock_code: str, price: float, volume: int, timestamp: datetime
    ) -> Optional[Order]:
        success, order, trade = self._execute_order(side, stock_code, price, volume, timestamp)
        if success:
            self.pending_orders.append(order)
            self.trades.append(trade)
        return order

    def next_day(self):
        if self.current_date is None:
            dates = sorted(self.data.keys())
            if not dates:
                return None
            trading_dates = [d for d in dates if MarketCalendar.is_trading_day(d)]
            if trading_dates:
                self.current_date = trading_dates[0]
            return
        else:
            next_date = None
            current_dt = datetime.strptime(self.current_date, '%Y-%m-%d')
            while True:
                next_date = next_date or current_dt + timedelta(days=1)
                next_date_str = next_date.strftime('%Y-%m-%d')
                if MarketCalendar.is_trading_day(next_date_str):
                    self.current_date = next_date_str
                    break
            if next_date is None:
                return

        self._settle_pending_orders()
        self._execute_pending_orders(self.current_date)

    def _settle_pending_orders(self):
        if not self.current_date:
            return
        if self.current_date not in self.data:
            return

        market_data = self.data[self.current_date]

        for code in list(self.position.keys()):
            pos = self.position[code]
            if code not in self.settlements:
                continue

            # Calculate settlement value
            original_date, settlement_value = self.settlements[code]
            if original_date == self.current_date:
                self.cash += settlement_value
                pos.settled = True
                del self.settlements[code]

    def _execute_pending_orders(self, date: str):
        if date not in self.data:
            return

        market_data = self.data[date]
        current_date_str = date

        for order in self.pending_orders:
            if order.status not in ['pending', 'partial']:
                continue

            current_price = market_data[market_data['date'] == current_date_str]['close'].values[0]

            if order.side == OrderSide.BUY:
                if order.order_type == OrderType.LIMIT and price > current_price:
                    continue

                order_value = order.price * order.volume * 100
                total_fee = order_value * self.fee_calculator.commission_rate
                total_fee = max(total_fee, self.fee_calculator.min_commission)

                remaining_cash = self.cash - sum(o.total_value for o in self.pending_orders 
                                                 if o.stock_code == order.stock_code)
                if remaining_cash < order_value + total_fee:
                    continue

                order.status = "partially_filled"
                self.cash -= order_value + total_fee

                # Update position
                if order.stock_code not in self.position:
                    self.position[order.stock_code] = Position(
                        stock_code=order.stock_code, open_price=order_price, volume=0,
                        avg_price=order.price, cost=0
                    )
                pos = self.position[order.stock_code]
                pos.volume += order.volume
                pos.avg_price = pos.cost / (pos.volume * 100) if pos.volume > 0 else order.price
                pos.cost = pos.cost + order_value

                order.total_value = order_value + total_fee
                order.net_value = order_value + total_fee
                self.cash -= order.net_value
            else:  # SELL
                # Calculate fees for sell
                commission, stamp_tax, transfer_fee = self.fee_calculator.calculate(
                    OrderSide.SELL, order.stock_code, order.price, order.volume
                )
                total_fee = commission + stamp_tax + transfer_fee

                # Calculate P&L
                if order.stock_code in self.position:
                    cost_per_share = self.position[order.stock_code].avg_price
                    pnl = (order.price - cost_per_share) * 100 * order.volume
                else:
                    pnl = 0

                net_value = order.total_value - total_fee + pnl
                self.cash += net_value

                # Update position
                pos = self.position.get(order.stock_code)
                if pos and pos.volume > 0:
                    pos.volume -= order.volume
                    pos.cost = pos.cost - (order.price * order.volume * 100)
                    pos.avg_price = pos.cost / (pos.volume * 100) if pos.volume > 0 else order.price
                else:
                    order.status = "rejected"

            order.filled_volume = order.volume
            order.status = "fully_filled"

    def get_cash(self) -> float:
        return self.cash

    def get_position(self, stock_code: str) -> Optional[Position]:
        return self.position.get(stock_code)

    def get_portfolio_summary(self) -> Dict:
        total_value = sum(p.volume * p.avg_price for p in self.position.values())
        total_cost = sum(p.cost for p in self.position.values())
        total_assets = self.cash + total_value

        return {
            'cash': self.cash,
            'positions': len(self.position),
            'total_stock_value': total_value,
            'total_assets': total_assets,
            'total_trades': len(self.trades),
            'final_value': total_assets
        }

    def get_trades_log(self) -> List[Dict]:
        return [
            {
                'timestamp': t.timestamp.strftime('%Y-%m-%d %H:%M:%S'),
                'trade_date': t.trade_date,
                'side': t.side,
                'stock_code': t.stock_code,
                'price': t.price,
                'volume': t.volume,
                'total_value': t.total_value,
                'fee': t.total_fee
            }
            for t in self.trades
        ]


class MomentumValueStrategy:
    """
    Momentum-Value Hybrid Strategy
    """

    def __init__(self, params: Dict):
        self.params = params
        self.price_periods = params.get('stock_selection', {}).get('ma_periods', [5, 10, 20, 60])
        self.volume_threshold = params.get('stock_selection', {}).get('volume_threshold', 1.5)
        self.momentum_lookback = params.get('stock_selection', {}).get('momentum_lookback', 20)

        self.max_single_position = params.get('position_management', {}).get('max_single_position', 0.25)
        self.max_total_position = params.get('position_management', {}).get('max_total_position', 0.80)
        self.initial_capital = params.get('position_management', {}).get('initial_capital', 1000000)

        self.trailing_stop = params.get('stop_loss', {}).get('trailing_stop', 0.08)
        self.fixed_stop = params.get('stop_loss', {}).get('fixed_stop', 0.10)
        self.time_stop_days = params.get('stop_loss', {}).get('time_stop_days', 30)

        self.target_profit = params.get('take_profit', {}).get('target', 0.20)
        self.partial_exit = params.get('take_profit', {}).get('partial_exit', 0.50)
        self.partial_exit_at = params.get('take_profit', {}).get('partial_exit_at', 0.12)

        self.max_daily_loss = params.get('risk_control', {}).get('max_daily_loss', 0.03)
        self.max_drawdown = params.get('risk_control', {}).get('max_drawdown', 0.15)
        self.max_consecutive_losses = params.get('risk_control', {}).get('max_consecutive_losses', 5)
        self.cool_down_days = params.get('risk_control', {}).get('cool_down_days', 3)

    def calculate_moving_averages(self, prices: np.ndarray) -> Dict[str, np.ndarray]:
        ma_dict = {}
        for period in self.price_periods:
            ma = np.convolve(prices, np.ones(period) / period, mode='valid')
            ma_dict[f'ma{period}'] = ma
        return ma_dict

    def get_ma_signal(self, ma_dict: Dict[str, np.ndarray]) -> int:
        buy_signal = 0
        sell_signal = 0

        if 'ma5' in ma_dict and 'ma10' in ma_dict and 'ma20' in ma_dict:
            if ma_dict['ma5'][-1] > ma_dict['ma10'][-1] and ma_dict['ma10'][-1] > ma_dict['ma20'][-1]:
                buy_signal = 1

        if 'ma10' in ma_dict and 'ma20' in ma_dict and 'ma60' in ma_dict:
            if ma_dict['ma10'][-1] < ma_dict['ma20'][-1] and ma_dict['ma20'][-1] < ma_dict['ma60'][-1]:
                sell_signal = 1

        return buy_signal if buy_signal > sell_signal else -sell_signal

    def generate_signals(
        self, stock_code: str, prices: np.ndarray, volumes: np.ndarray,
        current_date: datetime, last_signals: Dict[str, str]
    ) -> str:
        if len(prices) < max(self.price_periods) + 1:
            return 'neutral'

        ma_dict = self.calculate_moving_averages(prices)
        current_signal = self.get_ma_signal(ma_dict)

        if len(prices) > self.momentum_lookback + 1:
            n_ago = len(prices) - self.momentum_lookback - 1
            prices_ago = np.concatenate([np.zeros(self.momentum_lookback), prices[:-self.momentum_lookback]])
            ma_history = self.calculate_moving_averages(prices_ago)
        else:
            ma_history = ma_dict

        historical_signal = self.get_ma_signal(ma_history)

        avg_volume = np.mean(volumes[-self.momentum_lookback-1:-1]) if len(volumes) > self.momentum_lookback + 1 else 0
        relative_volume = volumes[-1] / avg_volume if avg_volume > 0 else 1

        if current_signal == 1 and historical_signal == -1:
            if relative_volume > self.volume_threshold:
                return 'buy'
        elif current_signal == -1 and historical_signal == 1:
            if relative_volume > self.volume_threshold:
                return 'sell'

        return 'neutral'

    def check_risk_controls(self, current_value: float, peak_value: float, 
                          daily_return: float, consecutive_losses: int) -> bool:
        if daily_return < -self.max_daily_loss:
            return False
        if peak_value > 0:
            drawdown = (peak_value - current_value) / peak_value
            if drawdown > self.max_drawdown:
                return False
        if consecutive_losses >= self.max_consecutive_losses:
            return False
        return True

    def evaluate_strategy(self, market_data: pd.DataFrame, stock_code: str) -> Dict:
        df = market_data.copy()
        df = df.set_index('date')
        df = df.loc[:df.index[-1]]

        close_prices = df['close'].values
        volumes = df['volume'].values

        if len(close_prices) < max(self.price_periods) + 1:
            return {'signal': 'neutral'}

        signals = self.generate_signals(stock_code, close_prices, volumes, df.index[-1], {stock_code: 'neutral'})

        return {'signal': signals}


class BacktestRunner:
    """
    Backtest Runner for Strategy Testing
    """

    def __init__(self, initial_capital: float = 1000000):
        self.initial_capital = initial_capital
        self.market_data: Dict[str, pd.DataFrame] = {}
        self.stock_reference: Dict[str, Dict] = {}
        self.stock_list: List[str] = []

        self.cash = initial_capital
        self.position: Dict[str, Position] = {}
        self.portfolio_value_history: List[Tuple[str, float]] = []
        self.daily_pnl: List[Tuple[str, float]] = []
        self.trades: List[Trade] = []
        self.cooling_down = False
        self.last_trade_date = None
        self.consecutive_losses = 0

        self.fee_calculator = None
        self.holidays = {}

    def load_data(self, data_dir: str):
        self.market_data = MarketDataLoader(data_dir)
        self.market_data.load_all()

        ref_dir = os.path.join(os.path.dirname(data_dir), 'reference')
        self.stock_reference = ConfigLoader.load_stock_reference_csv(
            os.path.join(ref_dir, 'stock_list_v2.csv')
        )

        self.stock_list = [s for s in self.stock_reference.keys() if s in self.market_data.data]

    def _calculate_portfolio_value(self) -> float:
        return self.cash + sum(
            pos.volume * pos.avg_price for pos in self.position.values()
        )

    def check_risk_controls(self):
        current_value = self._calculate_portfolio_value()

        if len(self.portfolio_value_history) > 1:
            prev_value = self.portfolio_value_history[-2][1]
        else:
            prev_value = self.initial_capital

        if prev_value == 0:
            prev_value = self.initial_capital

        daily_return = (current_value - prev_value) / prev_value
        peak_value = max([v[1] for v in self.portfolio_value_history])

        if self.cooling_down:
            return False

        if daily_return < -self.max_daily_loss:
            return False

        if peak_value > 0:
            drawdown = (peak_value - current_value) / peak_value
            if drawdown > self.max_drawdown:
                return False

        if len(self.daily_pnl) > 0:
            losses = sum(1 for _, pnl in self.daily_pnl if pnl < 0)
            if losses >= self.max_consecutive_losses:
                return False

        return True

    def _run_day(self, current_date: str):
        if not MarketCalendar.is_trading_day(current_date):
            return

        if current_date in self.holidays:
            return

        if current_date not in self.market_data.data:
            return

        market_data = self.market_data.data[current_date]
        current_price = market_data[market_data['date'] == current_date]['close'].values[0]
        current_volume = market_data[market_data['date'] == current_date]['volume'].values[0]

        # Record portfolio value
        value = self._calculate_portfolio_value()
        self.portfolio_value_history.append((current_date, value))

        # Calculate daily return
        if len(self.portfolio_value_history) > 1:
            prev_value = self.portfolio_value_history[-2][1]
            daily_return = (value - prev_value) / prev_value if prev_value > 0 else 0
        else:
            daily_return = 0

        self.daily_pnl.append((current_date, value - prev_value if len(self.portfolio_value_history) > 1 else 0))

        # Check risk controls
        if not self.check_risk_controls():
            self.cooling_down = True
            return

        # Execute signals for each stock
        for code in self.stock_list:
            if code not in self.market_data.data:
                continue

            df = self.market_data.data[code]
            prices = df[df['date'] == current_date]['close'].values
            volumes = df[df['date'] == current_date]['volume'].values

            if len(prices) < max(self.price_periods) + 2:
                continue

            # Check cooldown
            if self.last_trade_date and (current_date - self.last_trade_date).days < self.cool_down_days:
                continue

            signal = self.strategy.evaluate_strategy(self.market_data.data[code], code)

            if signal['signal'] == 'buy':
                self._execute_buy(code, current_price, current_volume)
            elif signal['signal'] == 'sell':
                if code in self.position and self.position[code].volume > 0:
                    self._execute_sell(code, current_price, current_volume)

        self.last_trade_date = current_date

    def _execute_buy(self, code: str, current_price: float, current_volume: float):
        if code not in self.stock_reference:
            return

        ref = self.stock_reference[code]
        lot_size = ref.get('lot_size', 100)
        price_limit = ref.get('price_limit', 0.10)

        price_value = current_price * 100
        lots_to_buy = min(int(self.cash / price_value), lot_size)
        lots_to_buy = (lots_to_buy // lot_size) * lot_size

        if lots_to_buy < lot_size:
            return

        order = Order(
            side=OrderSide.BUY, stock_code=code, order_type=OrderType.LIMIT,
            price=current_price, volume=lots_to_buy
        )

        total_value = order.price * order.volume * 100
        total_fee = self.fee_calculator.calculate(
            OrderSide.BUY, code, current_price, order.volume
        )
        total_fee = (total_fee[0], total_fee[1], total_fee[2])
        total_fee = sum(total_fee)

        if self.cash >= total_value + total_fee:
            self.cash -= total_value + total_fee

            trade = Trade(
                side=OrderSide.BUY, stock_code=code, price=current_price,
                volume=order.volume, total_value=order.total_value,
                timestamp=datetime.now(), trade_date=current_date,
                settlement_date=MarketCalendar.get_settlement_date(current_date)
            )
            trade.commission = total_fee[0]
            trade.stamp_tax = total_fee[1]
            trade.transfer_fee = total_fee[2]
            trade.total_fee = total_fee
            trade.net_value = order_value - total_fee

            self.trades.append(trade)
            self.last_trade_date = current_date
            self.consecutive_losses = 0

    def _execute_sell(self, code: str, current_price: float, current_volume: float):
        if code not in self.position or self.position[code].volume <= 0:
            return

        pos = self.position[code]
        lots_to_sell = pos.volume // 100 * 100  # Sell in lots of 100

        if lots_to_sell == 0:
            return

        order = Order(
            side=OrderSide.SELL, stock_code=code, order_type=OrderType.LIMIT,
            price=current_price, volume=lots_to_sell // 100
        )

        total_value = order.price * order.volume * 100
        total_fee = self.fee_calculator.calculate(
            OrderSide.SELL, code, current_price, order.volume
        )
        total_fee = (total_fee[0], total_fee[1], total_fee[2])
        total_fee = sum(total_fee)

        # Calculate P&L
        pnl = (current_price - pos.avg_price) * 100 * order.volume

        net_value = total_value - total_fee + pnl
        self.cash += net_value

        # Update position
        pos.volume -= order.volume
        if pos.volume == 0:
            del self.position[code]

        trade = Trade(
            side=OrderSide.SELL, stock_code=code, price=current_price,
            volume=order.volume, total_value=order.total_value,
            timestamp=datetime.now(), trade_date=current_date,
            settlement_date=MarketCalendar.get_settlement_date(current_date)
        )
        trade.commission = total_fee[0]
        trade.stamp_tax = total_fee[1]
        trade.transfer_fee = total_fee[2]
        trade.total_fee = total_fee
        trade.net_value = net_value

        self.trades.append(trade)
        self.last_trade_date = current_date
        self.consecutive_losses = 0

    def run_backtest(self, stock_codes: List[str] = None):
        if stock_codes is None:
            stock_codes = self.stock_list

        all_dates = set()
        for code, df in self.market_data.data.items():
            if code in stock_codes:
                all_dates.update(df['date'].dropna())

        if not all_dates:
            return {'error': 'No trading data found'}

        trading_dates = sorted([d for d in all_dates if MarketCalendar.is_trading_day(d)])
        if not trading_dates:
            return {'error': 'No trading days found'}

        self.strategy = MomentumValueStrategy({
            'initial_capital': self.initial_capital,
            'max_single_position': 0.25,
            'max_total_position': 0.80,
            'price_periods': [5, 10, 20, 60],
            'volume_threshold': 1.5,
            'momentum_lookback': 20,
            'max_drawdown': 0.15,
            'max_daily_loss': 0.03,
            'max_consecutive_losses': 5,
            'cool_down_days': 3
        })

        if self.fee_calculator is None:
            fee_file = os.path.join(os.path.dirname(__file__), 'config', 'trading_fees.json')
            if os.path.exists(fee_file):
                fee_config = ConfigLoader.load_json(fee_file)
                self.fee_calculator = FeeCalculator(fee_config)

        for date in trading_dates:
            self._run_day(date)

        return self._generate_results()

    def _generate_results(self) -> Dict:
        values = [v[1] for v in self.portfolio_value_history]

        if len(values) < 2:
            total_return = 0.0
        else:
            total_return = (values[-1] - values[0]) / values[0] * 100 if values[0] > 0 else 0

        peak_value = max(values) if values else self.initial_capital
        max_drawdown = 0
        if values:
            current = values[0]
            for v in values:
                if v > current:
                    current = v
                if current > 0:
                    dd = (current - v) / current
                    if dd > max_drawdown:
                        max_drawdown = dd

        if len(values) > 1:
            returns = [values[i] / values[i-1] - 1 for i in range(1, len(values))]
            if len(returns) > 0:
                mean_return = np.mean(returns)
                std_return = np.std(returns)
                sharpe_ratio = (mean_return - 0.03) / std_return if std_return > 0 else 0
            else:
                sharpe_ratio = 0
        else:
            sharpe_ratio = 0

        buy_trades = [t for t in self.trades if t.side == OrderSide.BUY]
        sell_trades = [t for t in self.trades if t.side == OrderSide.SELL]
        total_trades = len(self.trades)

        trade_returns = []
        for t in sell_trades:
            for bt in buy_trades:
                if bt.stock_code == t.stock_code and bt.timestamp.date() < t.timestamp.date():
                    buy_value = bt.total_value - bt.total_fee
                    sell_value = t.total_value
                    if buy_value > 0:
                        trade_returns.append((sell_value / buy_value) - 1)
                    break

        trade_win_rate = sum(1 for r in trade_returns if r > 0) / len(trade_returns) * 100 if trade_returns else 0

        results = {
            'total_return': total_return,
            'max_drawdown': max_drawdown,
            'sharpe_ratio': sharpe_ratio,
            'win_rate': win_rate if len(self.daily_pnl) > 0 else 0,
            'total_trades': total_trades,
            'buy_trades': len(buy_trades),
            'sell_trades': len(sell_trades),
            'trade_win_rate': trade_win_rate,
            'final_value': values[-1] if values else self.initial_capital,
            'trade_log': [
                {
                    'timestamp': t.timestamp.strftime('%Y-%m-%d %H:%M:%S'),
                    'trade_date': t.trade_date,
                    'side': 'Buy' if t.side == OrderSide.BUY else 'Sell',
                    'stock_code': t.stock_code,
                    'price': t.price,
                    'volume': t.volume,
                    'total_value': t.total_value,
                    'fee': t.total_fee
                }
                for t in self.trades
            ]
        }

        return results


